import { useState, useEffect, useRef } from "react";

const P = "#d60006", S = "#005da8", WHITE = "#fff", LIGHT = "#f8f9fb", DARK = "#111827", GRAY = "#6b7280", BORDER = "#e5e7eb";

const USERS = [
  { uid: "admin1", name: "Admin Geral", email: "admin@empresa.com", password: "admin123", role: "admin" },
  { uid: "emp1", name: "João Silva", email: "joao@empresa.com", password: "123456", role: "employee" },
  { uid: "emp2", name: "Maria Costa", email: "maria@empresa.com", password: "123456", role: "employee" },
  { uid: "emp3", name: "Pedro Alves", email: "pedro@empresa.com", password: "123456", role: "employee" },
];
const INIT_PROJECTS = [
  { id: "p1", name: "Obra - Rua das Flores", status: "active" },
  { id: "p2", name: "Instalação - Centro Comercial", status: "active" },
  { id: "p3", name: "Manutenção - Edifício Torre", status: "active" },
];
const INIT_RECORDS = [
  { id: "r1", userId: "emp1", date: "2025-05-01", entry: "07:30", exit: "18:45", location: "external", projectId: "p1", notes: "" },
  { id: "r2", userId: "emp1", date: "2025-05-02", entry: "08:00", exit: "18:00", location: "office", projectId: "p2", notes: "" },
  { id: "r3", userId: "emp2", date: "2025-05-01", entry: "08:15", exit: "19:30", location: "external", projectId: "p1", notes: "" },
  { id: "r4", userId: "emp2", date: "2025-05-02", entry: "07:45", exit: "17:00", location: "office", projectId: "p3", notes: "" },
  { id: "r5", userId: "emp3", date: "2025-05-01", entry: "08:00", exit: "20:00", location: "external", projectId: "p2", notes: "" },
  { id: "r6", userId: "emp1", date: "2025-05-05", entry: "06:00", exit: "18:00", location: "external", projectId: "p1", notes: "Urgente" },
];

const toMins = t => { const [h, m] = t.split(":").map(Number); return h * 60 + m; };
const toHrs = m => { const h = Math.floor(Math.abs(m) / 60), mn = Math.abs(m) % 60; return `${h}h${mn > 0 ? mn + "m" : ""}`; };
const initials = n => n.split(" ").map(x => x[0]).join("").slice(0, 2).toUpperCase();
function calcExtra(entry, exit) {
  const s = toMins(entry), e = toMins(exit), total = e - s;
  let extra = 0;
  if (s < 480) extra += 480 - s;
  if (e > 1080) extra += e - 1080;
  return { total, normal: Math.max(total - extra, 0), extra };
}

// ─── GLOBAL STYLES ────────────────────────────────────────────────────────────
const GlobalStyles = () => (
  <style>{`
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    body { font-family: 'Segoe UI', system-ui, sans-serif; background: ${LIGHT}; color: ${DARK}; }
    @keyframes fadeUp { from { opacity:0; transform:translateY(18px); } to { opacity:1; transform:translateY(0); } }
    @keyframes fadeIn { from { opacity:0; } to { opacity:1; } }
    @keyframes slideIn { from { opacity:0; transform:translateX(-16px); } to { opacity:1; transform:translateX(0); } }
    @keyframes scaleIn { from { opacity:0; transform:scale(0.93); } to { opacity:1; transform:scale(1); } }
    @keyframes spin { to { transform: rotate(360deg); } }
    @keyframes countUp { from { opacity:0; transform:scale(0.7); } to { opacity:1; transform:scale(1); } }
    @keyframes shimmer { 0%{background-position:-400px 0} 100%{background-position:400px 0} }
    @keyframes pulse { 0%,100%{opacity:1} 50%{opacity:.5} }
    .fade-up { animation: fadeUp 0.4s cubic-bezier(.22,.68,0,1.2) both; }
    .fade-in { animation: fadeIn 0.3s ease both; }
    .scale-in { animation: scaleIn 0.3s cubic-bezier(.22,.68,0,1.2) both; }
    .nav-item { transition: all 0.2s ease; }
    .nav-item:hover { background: #fff5f5 !important; color: ${P} !important; padding-left: 26px !important; }
    .btn-primary { transition: all 0.2s ease; }
    .btn-primary:hover { filter: brightness(1.1); transform: translateY(-1px); box-shadow: 0 4px 14px rgba(214,0,6,0.35); }
    .btn-primary:active { transform: translateY(0); }
    .btn-secondary { transition: all 0.2s ease; }
    .btn-secondary:hover { filter: brightness(1.1); transform: translateY(-1px); box-shadow: 0 4px 14px rgba(0,93,168,0.35); }
    .btn-ghost { transition: all 0.2s ease; }
    .btn-ghost:hover { background: ${LIGHT} !important; color: ${DARK} !important; }
    .stat-card { transition: transform 0.25s ease, box-shadow 0.25s ease; cursor: default; }
    .stat-card:hover { transform: translateY(-4px); box-shadow: 0 12px 28px rgba(0,0,0,0.13); }
    .table-row { transition: background 0.15s ease; }
    .table-row:hover td { background: #fafafa; }
    .card { transition: box-shadow 0.2s ease; }
    .card:hover { box-shadow: 0 4px 20px rgba(0,0,0,0.09); }
    .tag-btn { transition: all 0.18s ease; }
    .tag-btn:hover { border-color: ${P} !important; color: ${P} !important; }
    .input-field { transition: border 0.2s ease, box-shadow 0.2s ease; }
    .input-field:focus { border-color: ${S} !important; box-shadow: 0 0 0 3px rgba(0,93,168,0.12); outline: none; }
    .badge { display:inline-flex; align-items:center; gap:4px; }
    .modal-overlay { animation: fadeIn 0.2s ease both; }
    .modal-card { animation: scaleIn 0.25s cubic-bezier(.22,.68,0,1.2) both; }
    .sidebar-logo { background: linear-gradient(135deg, ${P}, #ff4444); -webkit-background-clip: text; -webkit-text-fill-color: transparent; }
    ::-webkit-scrollbar { width: 6px; } ::-webkit-scrollbar-track { background: transparent; } ::-webkit-scrollbar-thumb { background: #d1d5db; border-radius: 3px; }
  `}</style>
);

// ─── ANIMATED COUNTER ────────────────────────────────────────────────────────
function AnimatedNumber({ value, duration = 800 }) {
  const [display, setDisplay] = useState(0);
  const num = parseInt(value) || 0;
  useEffect(() => {
    let start = 0, step = num / (duration / 16);
    if (num === 0) { setDisplay(0); return; }
    const t = setInterval(() => {
      start += step;
      if (start >= num) { setDisplay(num); clearInterval(t); }
      else setDisplay(Math.floor(start));
    }, 16);
    return () => clearInterval(t);
  }, [num, duration]);
  return <span>{display}</span>;
}

// ─── STAT CARD ───────────────────────────────────────────────────────────────
function StatCard({ num, label, color, icon, delay = 0 }) {
  return (
    <div className="stat-card fade-up" style={{ background: `linear-gradient(135deg, ${color}, ${color}dd)`, borderRadius: 16, padding: "22px 24px", color: WHITE, boxShadow: `0 4px 16px ${color}44`, animationDelay: `${delay}ms` }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
        <div>
          <div style={{ fontSize: 32, fontWeight: 800, letterSpacing: -1, animation: "countUp 0.5s ease both" }}>{num}</div>
          <div style={{ fontSize: 13, opacity: 0.85, marginTop: 4, fontWeight: 500 }}>{label}</div>
        </div>
        <div style={{ fontSize: 28, opacity: 0.7 }}>{icon}</div>
      </div>
    </div>
  );
}

// ─── INPUT / SELECT ───────────────────────────────────────────────────────────
const Inp = ({ style, ...p }) => <input className="input-field" style={{ width: "100%", padding: "10px 13px", borderRadius: 10, border: `1.5px solid ${BORDER}`, fontSize: 14, background: WHITE, color: DARK, ...style }} {...p} />;
const Sel = ({ style, ...p }) => <select className="input-field" style={{ width: "100%", padding: "10px 13px", borderRadius: 10, border: `1.5px solid ${BORDER}`, fontSize: 14, background: WHITE, color: DARK, ...style }} {...p} />;

// ─── BUTTON ───────────────────────────────────────────────────────────────────
function Btn({ variant = "primary", children, style, ...p }) {
  const base = { padding: "10px 20px", borderRadius: 10, border: "none", cursor: "pointer", fontSize: 14, fontWeight: 600, display: "inline-flex", alignItems: "center", gap: 6 };
  const variants = {
    primary: { background: `linear-gradient(135deg, ${P}, #ff2222)`, color: WHITE },
    secondary: { background: `linear-gradient(135deg, ${S}, #0077cc)`, color: WHITE },
    ghost: { background: "transparent", color: GRAY, border: `1.5px solid ${BORDER}` },
    danger: { background: "#fee2e2", color: "#dc2626", border: "1.5px solid #fecaca" },
  };
  return <button className={`btn-${variant}`} style={{ ...base, ...variants[variant], ...style }} {...p}>{children}</button>;
}

// ─── BADGE ────────────────────────────────────────────────────────────────────
function Badge({ color, children }) {
  const colors = {
    green: { bg: "#dcfce7", text: "#16a34a" },
    red: { bg: "#fee2e2", text: "#dc2626" },
    blue: { bg: "#dbeafe", text: "#1d4ed8" },
    gray: { bg: "#f3f4f6", text: GRAY },
    purple: { bg: "#ede9fe", text: "#7c3aed" },
  };
  const c = colors[color] || colors.gray;
  return <span className="badge" style={{ padding: "4px 12px", borderRadius: 20, fontSize: 12, fontWeight: 600, background: c.bg, color: c.text }}>{children}</span>;
}

// ─── CARD ────────────────────────────────────────────────────────────────────
function Card({ children, style, delay = 0 }) {
  return <div className="card fade-up" style={{ background: WHITE, borderRadius: 16, padding: 24, marginBottom: 20, boxShadow: "0 1px 6px rgba(0,0,0,0.07)", border: `1px solid ${BORDER}`, animationDelay: `${delay}ms`, ...style }}>{children}</div>;
}

// ─── MODAL ───────────────────────────────────────────────────────────────────
function Modal({ title, children, onClose }) {
  return (
    <div className="modal-overlay" style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.45)", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 1000, backdropFilter: "blur(3px)" }}>
      <div className="modal-card" style={{ background: WHITE, borderRadius: 20, padding: 32, width: 400, boxShadow: "0 20px 60px rgba(0,0,0,0.2)" }}>
        <div style={{ fontSize: 18, fontWeight: 700, marginBottom: 16 }}>{title}</div>
        {children}
        <button style={{ position: "absolute", top: 16, right: 16, background: "none", border: "none", cursor: "pointer", fontSize: 20, color: GRAY }} onClick={onClose}>✕</button>
      </div>
    </div>
  );
}

// ─── ALERT ───────────────────────────────────────────────────────────────────
function Alert({ type, children }) {
  const colors = { success: ["#dcfce7", "#16a34a"], error: ["#fee2e2", "#dc2626"], info: ["#dbeafe", "#1d4ed8"] };
  const [bg, text] = colors[type] || colors.info;
  return <div className="fade-up" style={{ padding: "12px 16px", borderRadius: 10, marginBottom: 16, fontSize: 14, background: bg, color: text, fontWeight: 500, display: "flex", alignItems: "center", gap: 8 }}>{children}</div>;
}

// ─── LOGIN ───────────────────────────────────────────────────────────────────
function LoginPage({ onLogin }) {
  const [email, setEmail] = useState(""), [pass, setPass] = useState(""), [err, setErr] = useState(""), [loading, setLoading] = useState(false);
  const handle = () => {
    setLoading(true); setErr("");
    setTimeout(() => {
      const u = USERS.find(u => u.email === email && u.password === pass);
      u ? onLogin(u) : setErr("Email ou senha incorretos.");
      setLoading(false);
    }, 600);
  };
  return (
    <div style={{ minHeight: "100vh", display: "flex", alignItems: "center", justifyContent: "center", background: `linear-gradient(135deg, ${P} 0%, #a00004 40%, ${S} 100%)`, position: "relative", overflow: "hidden" }}>
      <div style={{ position: "absolute", inset: 0, backgroundImage: "radial-gradient(circle at 20% 50%, rgba(255,255,255,0.05) 0%, transparent 50%), radial-gradient(circle at 80% 20%, rgba(255,255,255,0.05) 0%, transparent 50%)" }} />
      <div className="scale-in" style={{ background: WHITE, borderRadius: 24, padding: 44, width: 380, boxShadow: "0 24px 64px rgba(0,0,0,0.2)", position: "relative" }}>
        <div style={{ textAlign: "center", marginBottom: 28 }}>
          <div style={{ width: 64, height: 64, borderRadius: 20, background: `linear-gradient(135deg, ${P}, #ff3333)`, display: "inline-flex", alignItems: "center", justifyContent: "center", marginBottom: 16, boxShadow: `0 8px 24px ${P}55` }}>
            <span style={{ fontSize: 28 }}>⏱</span>
          </div>
          <div style={{ fontSize: 26, fontWeight: 800, color: DARK, letterSpacing: -0.5 }}>TimeTrack</div>
          <div style={{ fontSize: 14, color: GRAY, marginTop: 4 }}>Sistema de Marcação de Horas</div>
        </div>
        {err && <Alert type="error">⚠️ {err}</Alert>}
        <div style={{ marginBottom: 14 }}>
          <label style={{ fontSize: 13, fontWeight: 600, color: GRAY, marginBottom: 6, display: "block" }}>Email</label>
          <Inp type="email" value={email} onChange={e => setEmail(e.target.value)} placeholder="seu@email.com" />
        </div>
        <div style={{ marginBottom: 20 }}>
          <label style={{ fontSize: 13, fontWeight: 600, color: GRAY, marginBottom: 6, display: "block" }}>Senha</label>
          <Inp type="password" value={pass} onChange={e => setPass(e.target.value)} placeholder="••••••" onKeyDown={e => e.key === "Enter" && handle()} />
        </div>
        <Btn variant="primary" style={{ width: "100%", justifyContent: "center", padding: 13, fontSize: 15 }} onClick={handle} disabled={loading}>
          {loading ? <><div style={{ width: 16, height: 16, border: "2px solid #fff5", borderTop: "2px solid #fff", borderRadius: "50%", animation: "spin 0.7s linear infinite" }} /> A entrar...</> : "Entrar →"}
        </Btn>
        <div style={{ marginTop: 20, fontSize: 12, color: GRAY, textAlign: "center", padding: "12px", background: LIGHT, borderRadius: 10 }}>
          <b>Demo:</b> admin@empresa.com / admin123<br />joao@empresa.com / 123456
        </div>
      </div>
    </div>
  );
}

// ─── EMP DASHBOARD ───────────────────────────────────────────────────────────
function EmpDashboard({ user, records, projects }) {
  const today = new Date().toISOString().split("T")[0];
  const todayRec = records.find(r => r.date === today);
  const totalExtra = records.reduce((a, r) => a + calcExtra(r.entry, r.exit).extra, 0);
  const thisMonth = records.filter(r => r.date.startsWith(new Date().toISOString().slice(0, 7)));
  return (
    <div>
      <div className="fade-up" style={{ fontSize: 24, fontWeight: 800, marginBottom: 24, color: DARK }}>Olá, {user.name.split(" ")[0]}! 👋</div>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(3,1fr)", gap: 16, marginBottom: 24 }}>
        <StatCard num={records.length} label="Dias Registados" color={S} icon="📅" delay={0} />
        <StatCard num={toHrs(totalExtra)} label="Total Horas Extras" color={P} icon="⚡" delay={80} />
        <StatCard num={thisMonth.length} label="Dias este mês" color="#16a34a" icon="📊" delay={160} />
      </div>
      <Card delay={200}>
        <div style={{ fontSize: 15, fontWeight: 700, marginBottom: 16, display: "flex", alignItems: "center", gap: 8 }}>📅 <span>Hoje — {today}</span></div>
        {todayRec ? (
          <div style={{ display: "flex", gap: 24, flexWrap: "wrap" }}>
            {[["Entrada", todayRec.entry, "🟢"], ["Saída", todayRec.exit, "🔴"], ["Local", todayRec.location === "external" ? "Externo" : "Escritório", todayRec.location === "external" ? "🏗" : "🏢"], ["Projeto", projects.find(p => p.id === todayRec.projectId)?.name || "-", "📁"]].map(([l, v, ic]) => (
              <div key={l} style={{ background: LIGHT, borderRadius: 10, padding: "12px 16px", minWidth: 110 }}>
                <div style={{ fontSize: 11, fontWeight: 600, color: GRAY, marginBottom: 4 }}>{ic} {l}</div>
                <div style={{ fontWeight: 700, fontSize: 15 }}>{v}</div>
              </div>
            ))}
            <div style={{ background: "#fff0f0", borderRadius: 10, padding: "12px 16px", minWidth: 110 }}>
              <div style={{ fontSize: 11, fontWeight: 600, color: GRAY, marginBottom: 4 }}>⚡ Extras hoje</div>
              <div style={{ fontWeight: 700, fontSize: 15, color: P }}>{toHrs(calcExtra(todayRec.entry, todayRec.exit).extra)}</div>
            </div>
          </div>
        ) : (
          <div style={{ color: GRAY, fontSize: 14, display: "flex", alignItems: "center", gap: 8, padding: "16px", background: LIGHT, borderRadius: 10 }}>
            ℹ️ Nenhum registo para hoje. Vá a "Registar Horas".
          </div>
        )}
      </Card>
      <Card delay={260}>
        <div style={{ fontSize: 15, fontWeight: 700, marginBottom: 16 }}>📋 Últimos Registos</div>
        <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 14 }}>
          <thead><tr>{["Data", "Entrada", "Saída", "Total", "Extra", "Local", "Projeto"].map(h => <th key={h} style={{ textAlign: "left", padding: "10px 12px", background: LIGHT, color: GRAY, fontWeight: 600, fontSize: 12, borderBottom: `1px solid ${BORDER}` }}>{h}</th>)}</tr></thead>
          <tbody>{[...records].sort((a, b) => b.date.localeCompare(a.date)).slice(0, 5).map(r => {
            const { total, extra } = calcExtra(r.entry, r.exit);
            return <tr key={r.id} className="table-row">
              <td style={{ padding: "11px 12px", borderBottom: `1px solid ${BORDER}` }}>{r.date}</td>
              <td style={{ padding: "11px 12px", borderBottom: `1px solid ${BORDER}` }}>{r.entry}</td>
              <td style={{ padding: "11px 12px", borderBottom: `1px solid ${BORDER}` }}>{r.exit}</td>
              <td style={{ padding: "11px 12px", borderBottom: `1px solid ${BORDER}` }}>{toHrs(total)}</td>
              <td style={{ padding: "11px 12px", borderBottom: `1px solid ${BORDER}` }}><span style={{ color: extra > 0 ? P : "#16a34a", fontWeight: 700 }}>{toHrs(extra)}</span></td>
              <td style={{ padding: "11px 12px", borderBottom: `1px solid ${BORDER}` }}><Badge color={r.location === "external" ? "blue" : "green"}>{r.location === "external" ? "Externo" : "Escritório"}</Badge></td>
              <td style={{ padding: "11px 12px", borderBottom: `1px solid ${BORDER}` }}>{projects.find(p => p.id === r.projectId)?.name || "-"}</td>
            </tr>;
          })}</tbody>
        </table>
      </Card>
    </div>
  );
}

// ─── EMP REGISTER ────────────────────────────────────────────────────────────
function EmpRegister({ user, records, setRecords, projects }) {
  const today = new Date().toISOString().split("T")[0];
  const [form, setForm] = useState({ date: today, entry: "", exit: "", location: "office", projectId: "", notes: "" });
  const [msg, setMsg] = useState(null);
  const active = projects.filter(p => p.status === "active");
  const save = () => {
    if (!form.entry || !form.exit || !form.projectId) { setMsg({ type: "error", text: "Preencha todos os campos obrigatórios." }); return; }
    if (toMins(form.exit) <= toMins(form.entry)) { setMsg({ type: "error", text: "Saída deve ser depois da entrada." }); return; }
    setRecords(prev => [...prev, { id: "r" + Date.now(), userId: user.uid, ...form }]);
    setMsg({ type: "success", text: "✅ Registo guardado com sucesso!" });
    setForm({ date: today, entry: "", exit: "", location: "office", projectId: "", notes: "" });
  };
  const preview = form.entry && form.exit && toMins(form.exit) > toMins(form.entry) ? calcExtra(form.entry, form.exit) : null;
  return (
    <div>
      <div className="fade-up" style={{ fontSize: 24, fontWeight: 800, marginBottom: 24 }}>Registar Horas</div>
      <Card>
        {msg && <Alert type={msg.type}>{msg.text}</Alert>}
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 16 }}>
          {[["Data *", "date", "date"], ["Hora de Entrada *", "entry", "time"], ["Hora de Saída *", "exit", "time"]].map(([l, k, t]) => (
            <div key={k}>
              <label style={{ fontSize: 13, fontWeight: 600, color: GRAY, marginBottom: 6, display: "block" }}>{l}</label>
              <Inp type={t} value={form[k]} onChange={e => setForm({ ...form, [k]: e.target.value })} />
            </div>
          ))}
          <div>
            <label style={{ fontSize: 13, fontWeight: 600, color: GRAY, marginBottom: 6, display: "block" }}>Projeto *</label>
            <Sel value={form.projectId} onChange={e => setForm({ ...form, projectId: e.target.value })}>
              <option value="">Selecione um projeto</option>
              {active.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
            </Sel>
          </div>
        </div>
        <div style={{ marginTop: 16, marginBottom: 16 }}>
          <label style={{ fontSize: 13, fontWeight: 600, color: GRAY, marginBottom: 10, display: "block" }}>Local de Trabalho *</label>
          <div style={{ display: "flex", gap: 10 }}>
            {[["office", "🏢 Escritório"], ["external", "🏗 Externo"]].map(([v, l]) => (
              <button key={v} className="tag-btn" onClick={() => setForm({ ...form, location: v })}
                style={{ padding: "10px 20px", borderRadius: 10, border: `2px solid ${form.location === v ? P : BORDER}`, background: form.location === v ? "#fff0f0" : WHITE, color: form.location === v ? P : GRAY, cursor: "pointer", fontSize: 14, fontWeight: form.location === v ? 700 : 400, transition: "all 0.2s ease" }}>
                {l}
              </button>
            ))}
          </div>
        </div>
        <div style={{ marginBottom: 20 }}>
          <label style={{ fontSize: 13, fontWeight: 600, color: GRAY, marginBottom: 6, display: "block" }}>Notas</label>
          <Inp value={form.notes} onChange={e => setForm({ ...form, notes: e.target.value })} placeholder="Observações..." />
        </div>
        {preview && (
          <div className="fade-up" style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 12, marginBottom: 20 }}>
            {[[S, "Total", toHrs(preview.total), "⏱"], ["#16a34a", "Normal", toHrs(preview.normal), "✅"], [preview.extra > 0 ? P : "#9ca3af", "Extra", toHrs(preview.extra), "⚡"]].map(([c, l, v, ic]) => (
              <div key={l} style={{ background: c, borderRadius: 12, padding: "14px 18px", color: WHITE }}>
                <div style={{ fontSize: 11, opacity: .8, marginBottom: 4 }}>{ic} {l}</div>
                <div style={{ fontSize: 22, fontWeight: 800 }}>{v}</div>
              </div>
            ))}
          </div>
        )}
        <Btn variant="primary" onClick={save}>💾 Guardar Registo</Btn>
      </Card>
    </div>
  );
}

// ─── EMP HISTORY ─────────────────────────────────────────────────────────────
function EmpHistory({ records, projects }) {
  const sorted = [...records].sort((a, b) => b.date.localeCompare(a.date));
  return (
    <div>
      <div className="fade-up" style={{ fontSize: 24, fontWeight: 800, marginBottom: 24 }}>Meu Histórico</div>
      <Card>
        <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 14 }}>
          <thead><tr>{["Data", "Entrada", "Saída", "Total", "Normal", "Extra", "Local", "Projeto"].map(h => <th key={h} style={{ textAlign: "left", padding: "10px 12px", background: LIGHT, color: GRAY, fontWeight: 600, fontSize: 12, borderBottom: `1px solid ${BORDER}` }}>{h}</th>)}</tr></thead>
          <tbody>{sorted.map(r => {
            const { total, normal, extra } = calcExtra(r.entry, r.exit);
            return <tr key={r.id} className="table-row">
              {[r.date, r.entry, r.exit, toHrs(total), toHrs(normal)].map((v, i) => <td key={i} style={{ padding: "11px 12px", borderBottom: `1px solid ${BORDER}` }}>{v}</td>)}
              <td style={{ padding: "11px 12px", borderBottom: `1px solid ${BORDER}` }}><span style={{ color: extra > 0 ? P : "#16a34a", fontWeight: 700 }}>{toHrs(extra)}</span></td>
              <td style={{ padding: "11px 12px", borderBottom: `1px solid ${BORDER}` }}><Badge color={r.location === "external" ? "blue" : "green"}>{r.location === "external" ? "Externo" : "Escritório"}</Badge></td>
              <td style={{ padding: "11px 12px", borderBottom: `1px solid ${BORDER}` }}>{projects.find(p => p.id === r.projectId)?.name || "-"}</td>
