          <thead><tr>{["Funcionário", "Registos", "Horas Normais", "Horas Extras", "Último Registo"].map(h => <th key={h} style={{ textAlign: "left", padding: "10px 12px", background: LIGHT, color: GRAY, fontWeight: 600, fontSize: 12, borderBottom: `1px solid ${BORDER}` }}>{h}</th>)}</tr></thead>
          <tbody>{emps.map(emp => {
            const recs = allRecords.filter(r => r.userId === emp.uid);
            const totalN = recs.reduce((a, r) => a + calcExtra(r.entry, r.exit).normal, 0);
